#include "dm/core.hpp"
#include <ctime>
#include <unistd.h>
#include <stdexcept>
namespace dm {
static const std::string base="https://api.real-debrid.com/",client="X245A4XAIBGVM";
Debrid::Debrid(Transport& t,std::string r):net(t),root(r){mkdirs(root);credentials=readJson(root+"/credentials.json",Json::object());}
bool Debrid::loggedIn()const{return credentials.contains("access_token");}
Json Debrid::call(std::string path,std::string method,std::string body,bool auth){if(auth&&!loggedIn())throw std::runtime_error("Authorize Real-Debrid first");if(auth&&credentials.value("expires_at",int64_t(0))<=std::time(nullptr)+30)token(credentials.at("refresh_token"));std::lock_guard<std::mutex> lock(gate);if(next-now()>2)throw std::runtime_error("API cooldown; retry later");if(next>now())sleepMs(int((next-now())*1000));Request r;r.url=base+path;r.method=method;r.body=body;r.headers["Content-Type"]="application/x-www-form-urlencoded";if(auth)r.headers["Authorization"]="Bearer "+credentials.at("access_token").get<std::string>();Response h;std::string data;fetch(net,r,[&](const Response& x){h=x;},[&](const char* p,size_t n){if(data.size()+n>4*1024*1024)throw std::runtime_error("API response too large");data.append(p,n);},stop);next=now()+0.5;if(h.status==429){uint64_t delay=60;try{if(h.headers.count("retry-after"))delay=number(h.headers.at("retry-after"));}catch(...){}next=now()+std::max<uint64_t>(1,std::min<uint64_t>(delay,86400));throw std::runtime_error("Real-Debrid rate limited");}Json j;try{j=data.empty()?Json::object():Json::parse(data);}catch(...){throw std::runtime_error("Invalid API JSON");}if(h.status<200||h.status>=300||j.contains("error"))throw std::runtime_error("Real-Debrid HTTP "+std::to_string(h.status)+" code "+std::to_string(j.value("error_code",0)));return j;}
void Debrid::token(const std::string& code){auto j=call("oauth/v2/token","POST","client_id="+encode(credentials.at("client_id"))+"&client_secret="+encode(credentials.at("client_secret"))+"&code="+encode(code)+"&grant_type="+encode("http://oauth.net/grant_type/device/1.0"),false);credentials["access_token"]=j.at("access_token");credentials["refresh_token"]=j.at("refresh_token");credentials["expires_at"]=int64_t(std::time(nullptr))+j.at("expires_in").get<int>();atomicJson(root+"/credentials.json",credentials);}
Json Debrid::begin(){auto j=call("oauth/v2/device/code?client_id="+client+"&new_credentials=yes","GET","",false);j["deadline"]=now()+j.at("expires_in").get<int>();j["next_poll"]=now()+std::max(5,j.at("interval").get<int>());pollAt=0;return j;}
bool Debrid::poll(const Json& device){if(now()>device.at("deadline").get<double>())throw std::runtime_error("Authorization expired");if(now()<pollAt)return false;pollAt=now()+std::max(5,device.value("interval",5));auto j=call("oauth/v2/device/credentials?client_id="+client+"&code="+encode(device.at("device_code")),"GET","",false);if(!j.contains("client_secret"))return false;credentials["client_id"]=j.at("client_id");credentials["client_secret"]=j.at("client_secret");token(device.at("device_code"));return true;}
void Debrid::logout(){credentials=Json::object();if(unlink((root+"/credentials.json").c_str())&&exists(root+"/credentials.json"))throw std::runtime_error("Credential removal failed");unlink((root+"/credentials.json.tmp").c_str());}
Json Debrid::account(){return call("rest/1.0/user");}Json Debrid::hosts(){return call("rest/1.0/hosts/domains","GET","",false);}Json Debrid::history(){return call("rest/1.0/downloads?limit=100");}Json Debrid::torrents(){return call("rest/1.0/torrents?limit=100");}Json Debrid::torrent(const std::string& id){return call("rest/1.0/torrents/info/"+encode(id));}Json Debrid::magnet(const std::string& s){if(s.rfind("magnet:?",0)!=0)throw std::runtime_error("Invalid magnet");return call("rest/1.0/torrents/addMagnet","POST","magnet="+encode(s));}void Debrid::select(const std::string& id,const std::string& files){call("rest/1.0/torrents/selectFiles/"+encode(id),"POST","files="+encode(files));}
Resolved Debrid::unrestrict(const std::string& u){Url::parse(u);auto j=call("rest/1.0/unrestrict/link","POST","link="+encode(u));auto link=j.at("download").get<std::string>();if(Url::parse(link).scheme!="https")throw std::runtime_error("Real-Debrid returned non-HTTPS link");return {link,safeName(j.at("filename")),j.value("filesize",uint64_t(0))};}
}
